package com.ivanwitt.mayasunmoon

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Base64

/**
 * User-supplied realistic Sun and Moon artwork, converted to transparent WebP and embedded directly
 * into the APK. The widget therefore never needs the internet to render the two moving bodies.
 */
object CelestialAssets {
    @Volatile private var cachedSun: Bitmap? = null
    @Volatile private var cachedMoon: Bitmap? = null

    fun sunBitmap(): Bitmap = cachedSun ?: synchronized(this) {
        cachedSun ?: decode(SUN_WEBP).also { cachedSun = it }
    }

    fun moonBitmap(): Bitmap = cachedMoon ?: synchronized(this) {
        cachedMoon ?: decode(MOON_WEBP).also { cachedMoon = it }
    }

    private fun decode(encoded: String): Bitmap {
        val data = Base64.decode(encoded, Base64.DEFAULT)
        return requireNotNull(BitmapFactory.decodeByteArray(data, 0, data.size)) {
            "Unable to decode embedded celestial artwork"
        }
    }

    private const val SUN_WEBP = ""

    private const val MOON_WEBP = ""
}
